import type { Scenario, Scene } from '../types';
import { ITEMS } from '../items';
import { largeAdventure, largeEnd, largeScene, largeTags } from './largeContentTools';

type SalvageStory = {
  id: string; title: string; subtitle: string; place: string; risk: 'LOW' | 'MODERATE' | 'HIGH';
  opening: string; firstChoices: [string, string, string];
  complication: string; consequence: [string, string, string];
  property: string; owner: string; gear?: string; gearSource?: string; gearCost?: number; repair?: boolean;
  repairItem?: string;
  coins: number; knowledge: string; lore?: string; combat?: { enemy: string; warning: string; winChance: number };
};

const stories: SalvageStory[] = [
  { id:'the-silted-toolbox', title:'The Toolbox at Low Water', subtitle:'A river gives back a work crew’s missing tools, but not their ownership marks.', place:'riverbank', risk:'MODERATE', opening:'A spring flood has left a timber toolbox lodged in reeds below a washed-out ferry landing. The ferry keeper, Ada Bell, says it belongs to the bridge crew upriver, but the lid is still under water and a second box-shaped object is caught nearer the current.', firstChoices:['Tie your Travel Rope to the sound landing post before reaching down','Use the Collapsible Sounding Rod to test the mud from firm ground','Wait for the bridge foreman to arrive before touching either object'], complication:'The first box opens to ordinary wrench marks and a crew inventory number. The nearer object is a private carpenter’s chest, its owner’s initials visible beneath silt. Water is rising again; recovering both would mean leaving one exposed.', consequence:['The rope steadies the crew box, but the current tugs hard enough that you must choose what to secure first.','The rod finds a firm shelf beneath the crew box; the other object remains beyond a safe reach.','The foreman recognizes both marks and confirms the private chest belongs to a carpenter expected downstream.'], property:'The bridge crew’s duplicate Pocket Toolkit is released to you under their written salvage agreement after their numbered kit is accounted for.', owner:'You return the carpenter’s marked chest to its owner, who pays the agreed two-coin finder fee.', gear:'pocketToolkit', gearSource:'Released as the bridge crew’s duplicate kit under Ada Bell’s signed salvage agreement; recovered from the spring flood at the ferry landing.', coins:2, knowledge:'A submerged load should be tested from stable footing before a line is pulled; current can turn a small box into a dangerous anchor.' },
  { id:'the-roof-under-ash', title:'The Roof Under Ash', subtitle:'A burned workshop leaves useful metal beneath unsafe rafters.', place:'workshop', risk:'HIGH', opening:'After a small shop fire, the owner permits recovery only from the brick side yard. A bent Lantern Guard lies near the wall; farther in, a tool roll is visible under a roof beam that still ticks as it cools.', firstChoices:['Use Heavy Leather Gloves to move loose hot fittings near the wall','Ask the owner to mark the no-entry line before recovery begins','Use a long hook from outside the wall to draw the tool roll clear'], complication:'The near-side fittings are safe to move, but smoke shifts from a gap beneath the fallen roof. The tool roll bears the apprentice’s initials, and a voice from the lane says the apprentice has already gone to stay with family.', consequence:['Your gloves let you handle the cooler iron without cutting your hands; the guard is repairable, but the inner roll remains under the beam.','The owner marks a clear boundary and confirms the apprentice’s kit is not part of the shop stock.','The hook moves the roll only as far as the brick sill; reaching farther would put you beneath the unstable roof.'], property:'The owner confirms the shop’s spare Lantern Guard is beyond repair and gives you the intact replacement from the closed stock, with ownership explicitly transferred.', owner:'You leave the apprentice’s marked roll for its owner and accept the two-coin recovery wage.', gear:'lanternGuard', gearSource:'A shop spare transferred by owner Cora Pell after fire-damaged stock was inventoried; the bent guard remains with the scrap iron.', coins:2, knowledge:'After a fire, a quiet roof can still shift as hidden heat escapes; recover from a safe boundary, not from the apparent edge of debris.' },
  { id:'the-siding-spill', title:'The Siding Spill', subtitle:'A freight crate has split open beside a quiet rail spur.', place:'railroad siding', risk:'LOW', opening:'At a siding, a handcart load of survey equipment has spilled when one wheel split. A railway clerk is checking the waybill while a track worker points out a brass instrument case below the embankment.', firstChoices:['Check the waybill and match the crate marks before lifting anything','Use the Compact Wheel Wrench to free the handcart’s trapped wheel','Ask the track worker to hold the cart while you retrieve the case'], complication:'The case is marked to a county survey party, but the listed Collapsible Sounding Rod is missing. A second, unlisted rod lies beside the track with a repair stamp from a different crew.', consequence:['The waybill establishes which equipment is freight and which rod was already trackside before the spill.','The wheel is held long enough to stop further crates sliding, though the case remains below the bank.','The worker steadies the cart; a clear inventory prevents the loose rod from being mistaken for freight.'], property:'The county surveyor confirms the recovered rod is their duplicate and releases it to you after the listed equipment is returned.', owner:'You return the listed case unopened and receive the clerk’s three-coin documented recovery fee.', gear:'collapsibleSoundingRod', gearSource:'Transferred by the county surveyor as a duplicate after the waybill inventory was reconciled; its former survey crew stamp remains legible.', coins:3, combat:{enemy:'siding thief',warning:'A man with a pry bar steps from the freight car behind the clerk and orders the case left; the staffed station office is close, and he has not blocked the road.',winChance:0.58}, knowledge:'Waybill marks can distinguish freight from equipment that was already beside a siding; compare the seal and item list before claiming a spill.', lore:'The spur once served a quarry whose survey stakes still appear in old county maps.' },
  { id:'the-camp-that-wasnt-empty', title:'The Camp That Wasn’t Empty', subtitle:'An apparently abandoned camp still has a watcher in the trees.', place:'forest wilderness', risk:'MODERATE', opening:'A canvas camp stands cold beside a cut trail. Its cook pot is gone, but fresh ash and a folded map case suggest the party left recently. A dry Travel Rope and a pair of Field Glasses are visible beneath a tarp.', firstChoices:['Call from the trail and give anyone inside time to answer','Study the fresh boot tracks without entering the tent ring','Use Field Glasses from the open rise to watch the tree line'], complication:'A young survey hand returns carrying water. She says the camp belongs to a delayed party and the tools are inventoried, but their leader told her to leave any damaged spare for the next crew.', consequence:['A voice answers from the ridge; no one was sleeping in the tent, but the party is still nearby.','The tracks lead to the water source and back, showing the camp was paused rather than abandoned.','You spot the survey hand before she reaches camp, avoiding a frightened meeting in the brush.'], property:'The returning surveyor confirms the camp’s spare Travel Rope was written off as frayed and explicitly releases it after you help retrieve the map case.', owner:'You leave all equipment in place, return the map case, and accept the survey hand’s one-coin thanks.', gear:'travelRope', gearSource:'Released by the survey leader as a written-off frayed spare after the map case and current crew inventory were recovered.', coins:1, knowledge:'A cold fire does not prove a camp is abandoned; fresh water trips and returning tracks can reveal a temporary absence.' },
  { id:'the-barn-wall-list', title:'The List Behind the Barn Wall', subtitle:'A storm-damaged barn exposes tools that two neighbors remember differently.', place:'farm', risk:'MODERATE', opening:'Wind has opened a section of an old barn wall. Two neighbors arrive with separate lists: one claims the tools were loaned to the farm, the other says they were left by a departed tenant. A carpenter’s square is nailed to a surviving brace.', firstChoices:['Compare initials on the tools with both written lists','Brace the leaning wall with the Steel Wedge before anyone reaches in','Ask the neighbors to describe the last repair rather than argue ownership'], complication:'The square bears the tenant’s mark, while the list shows it was sold to the current farmer years ago. A second item, a Gate Hook, has no mark and is buried under a cracked beam.', consequence:['The dates separate the square’s former owner from its current one; the paper trail is stronger than either recollection.','The wedge holds the brace long enough for a careful inventory; it does not make the wall safe to enter.','The farmer remembers replacing the hook after the tenant left, but cannot say who paid for it.'], property:'The farmer verifies the Gate Hook was his spare and releases it as your share for bracing and inventorying the wall; the marked square stays with him.', owner:'You refuse the disputed square, record both accounts for the county clerk, and accept two coins for safe bracing.', gear:'gateHook', gearSource:'Farmer Len Voss explicitly transfers his unmarked spare Gate Hook as payment; the Carpenter’s Square remains with its documented owner.', coins:2, knowledge:'Old marks establish an object’s history, not necessarily its present owner; date the mark against the latest sale or work list.' },
  { id:'the-quarry-winch', title:'The Quarry’s Last Lift', subtitle:'A retired quarryman asks for a winch component before the pit floods.', place:'quarry', risk:'HIGH', opening:'A quarry is being closed after water reached the lower cut. The retired foreman has permission to remove his crew’s tools, but a pulley block is wedged beside a cracked ledge. He offers salvage rights only for equipment his inventory rejects.', firstChoices:['Use the Compact Block-and-Tackle from the stable upper beam','Probe the ledge from outside with the Collapsible Sounding Rod','Ask the foreman to identify his own property before recovery'], complication:'The block is sound, but the line attached to it is not. Below, a metal case bears the quarry’s numbered stamp; the foreman says it contains his crew’s survey notes, not company property.', consequence:['The pulley takes weight gradually, but the frayed line must be replaced before the block can move.','The rod finds a hollow seam beside the ledge and rules out the direct approach.','The foreman identifies his notes and the company block separately, giving you a clean salvage boundary.'], property:'The foreman replaces the quarry’s block with a company-owned unit and transfers his personally owned Compact Block-and-Tackle to you after his notes are recovered.', owner:'You leave the block in place, recover the sealed notes from a safe shelf, and receive the agreed three-coin fee.', gear:'compactBlockAndTackle', gearSource:'Personally owned by retired foreman Oren Pike and explicitly transferred after the company issued his replacement; its old quarry tag remains attached.', coins:3, combat:{enemy:'rival quarry salvager',warning:'A rival worker steps onto the ledge and reaches for the pulley block, despite the foreman’s written claim. The loose rock makes a struggle risky, but the upper track remains open.',winChance:0.52}, knowledge:'A pulley block can multiply lifting force, but it cannot make a frayed line or cracked anchor safe.' },
  { id:'the-ferry-chest', title:'The Ferry Chest Below the Landing', subtitle:'A ferryman’s chest is trapped under a flooded landing, and a stranger claims it.', place:'river ferry', risk:'HIGH', opening:'The ferry landing shifted in a night flood. A small chest is visible beneath the downstream plank, and a traveler says it contains his tools. The ferryman recognizes the initials as belonging to a deckhand who left last month.', firstChoices:['Use the Sounding Rod to test the depth from the bank','Secure a rope to the landing before anyone steps onto it','Ask the claimant to name a contents mark that can be checked'], complication:'The depth is manageable near the bank, but the plank creaks under its own weight. The claimant correctly names a blue repair patch inside the lid; the ferryman remembers the former deckhand used blue thread.', consequence:['The rod finds a shallow shelf and a deeper channel beyond; the chest can be reached only from the bank side.','The rope stabilizes the loose plank, though it cannot carry a person’s full weight if the wood breaks.','The matching patch supports the claimant’s account, but the ferryman still wants the former deckhand contacted before the chest changes hands.'], property:'The ferryman reaches the former deckhand by the next boat; she authorizes the chest and explicitly gives you her spare Farm Whistle as thanks for the careful recovery.', owner:'You leave the chest sealed for its absent owner and take the ferryman’s two-coin fee for securing the landing.', gear:'farmWhistle', gearSource:'A personal spare gifted by the former deckhand after she authorized the chest recovery; the chest itself is returned intact.', coins:2, knowledge:'A correct contents detail can support a claim but does not replace checking with the named owner when that is practical.' },
  { id:'the-storm-cellar', title:'What the Storm Left in the Cellar', subtitle:'A fallen stair reveals a dry shelf and one household’s private stores.', place:'town edge', risk:'MODERATE', opening:'A storm has collapsed the outside cellar stair of an empty boarding house. The landlord has hired you to retrieve a ledger and says salvage is limited to items he rejects after inventory. A waxed canvas sheet lies folded above the broken steps.', firstChoices:['Cover the exposed ledger with the Waxed Canvas Sheet before moving debris','Use the Drainage Hook to clear loose boards from the cellar mouth','Ask the landlord to confirm which rooms are included in the recovery'], complication:'The ledger is dry, but a tin case below it carries a tenant’s name and recent rent receipts. The landlord admits the tenant left town only yesterday and has not surrendered the room.', consequence:['The sheet keeps rain off the ledger; the named tin remains private property and must not be opened.','The hook clears loose boards without placing your hands under them, revealing the tenant’s marked case.','The landlord narrows the job to public records and confirms the tenant’s belongings are excluded.'], property:'After the tenant returns and retrieves her case, the landlord explicitly releases his own sound Waxed Canvas Sheet to you as the agreed salvage share.', owner:'You recover only the public ledger and receive the two-coin contract fee; the tenant’s case stays sealed.', gear:'waxedCanvasSheet', gearSource:'Landlord’s own spare, released under the written salvage terms after the tenant reclaimed her private case.', coins:2, knowledge:'A hired recovery boundary matters: a room may be accessible without its contents being abandoned.' },
  { id:'the-charred-signal-post', title:'The Charred Signal Post', subtitle:'A roadside fire leaves a signal mirror buried among blackened boards.', place:'road bridge', risk:'LOW', opening:'A brush fire burned around a county signal post without reaching the road. A mirror lies under a charred board, and the local road crew says it may be their missing equipment. A glass worker passing by says it resembles a private survey mirror.', firstChoices:['Lift the board with a pry tool while keeping the mirror shaded','Check the road crew’s stamped inventory before handling it','Ask the glass worker to inspect the backing and maker’s mark'], complication:'The mirror has a county mark beneath soot and a private maker’s stamp on the handle. The road crew’s lost-item ledger lists a mirror but not its serial; the glass worker recognizes a repair seam from his own shop.', consequence:['The board comes free without scratching the mirror, but both marks remain relevant to its ownership.','The ledger confirms a loss report, not the item’s identity; the serial must be checked.','The seam matches the worker’s old repair, but he sold the mirror to the county crew last year.'], property:'The county foreman verifies the mirror’s serial and transfers an unissued spare Roadside Signal Mirror as your documented recovery compensation.', owner:'You return the found mirror to the crew and receive their one-coin finder payment.', gear:'roadsideSignalMirror', gearSource:'County foreman releases an unissued spare after the recovered mirror is matched to the public inventory; the charred mirror is restored to service.', coins:1, knowledge:'Maker marks and repair seams show an object’s path, while an inventory number is what links it to a current owner.' },
  { id:'the-missing-pack-frame', title:'The Pack Frame in the Ravine', subtitle:'A mule train lost a load below a trail, but the mule is more urgent than the gear.', place:'mountain trail', risk:'HIGH', opening:'A pack mule is safe on the trail, but its load has slid into a shallow ravine. The handler asks you to recover a frame and two tied bundles before afternoon rain. One bundle contains a sealed medicine parcel; the other is marked with a private outfitter’s stamp.', firstChoices:['Secure the mule and handler before approaching the ravine','Use Travel Rope from the upper trail to raise the pack frame','Check the medicine parcel’s seal before choosing what to recover first'], complication:'The frame can be lifted with a line, but the medicine bundle has snagged beneath a wet branch. The handler says the frame is rented and the stamped bundle belongs to the outfitter, who promised a usable replacement if their gear returned.', consequence:['The mule is calm and the handler can help direct a lift; there is time for one safe recovery before the rain.','The rope raises the frame steadily, but the snagged medicine bundle remains lower and may tear if pulled.','The seal is intact and the parcel belongs to the handler’s patient, making its priority clear without opening it.'], property:'The outfitter confirms the returned frame and medicine are intact, then releases a duplicate Pack Frame as compensation under the earlier agreement.', owner:'You prioritize and recover the sealed medicine; the handler pays three coins and leaves the rented frame for its owner.', gear:'packFrame', gearSource:'Duplicate frame explicitly released by the outfitter after the rented frame was returned and the sealed parcel delivered.', coins:3, knowledge:'A suspended pack should be lifted from its frame points; pulling a tied parcel can damage both its wrapping and contents.' },
  { id:'the-lost-lantern-crate', title:'The Lantern Crate in the Washout', subtitle:'A road crew’s lanterns are trapped behind a fresh bank collapse.', place:'washed-out road', risk:'MODERATE', opening:'A road washout exposed a crate of lanterns beneath the old shoulder. The crew’s foreman confirms the crate was lost in last month’s storm and has a salvage agreement with the county: damaged stock may be kept after the usable lamps are returned.', firstChoices:['Use the Steel Wedge to hold the loose shoulder while inspecting from above','Shine your Lantern from the stable road edge and count the crate contents','Ask the foreman to mark which lanterns remain county property'], complication:'Three lanterns are intact; one has a cracked chimney. A second crate is buried farther under the bank, but it may be supporting the exposed shelf.', consequence:['The wedge holds a small stone in place, but the larger shelf still shifts and must not be entered.','The light reveals the cracked glass without requiring anyone to climb down.','The foreman marks the intact lamps for return and confirms the damaged one is covered by the salvage terms.'], property:'The crew receives the three serviceable lamps; the foreman explicitly releases the damaged Roadman’s Lantern to you for parts and repair.', owner:'You leave the lantern with the county repair shop and accept two coins for the inventory work.', gear:'roadmansLantern', gearSource:'Damaged county lantern explicitly released under the salvage agreement after all usable lamps were returned; recorded as recovered from the washout.', coins:2, repair:true, repairItem:'roadmansLantern', knowledge:'A buried crate may support a bank; remove only what the owner authorized and never assume the exposed edge is stable.' },
  { id:'the-ledger-in-the-weir', title:'The Ledger at the Weir', subtitle:'A mill ledger is trapped in a jam of branches, and its figures may settle a wage dispute.', place:'river weir', risk:'MODERATE', opening:'A mill ledger has washed into the downstream side of a weir. The miller wants it back before the workers arrive, but one worker says the book contains proof of unpaid wages. The book’s clasp bears the mill seal.', firstChoices:['Use the Drainage Hook from the stone walk, not from the water','Ask the worker whether a page or the whole book is at issue','Check the mill seal without opening the clasp'], complication:'The ledger is private mill property, but the workers have a legitimate claim to copies of their own entries. Water is climbing over the lower stones; there is time to recover the book, not to read it here.', consequence:['The hook catches the leather cover and brings it within reach without putting you in the current.','The worker explains that names and sums matter, not the mill’s unrelated accounts.','The seal is intact, so no one can claim the pages were altered during recovery.'], property:'The miller returns the ledger to the locked office and gives you a duplicate Drainage Hook from his river crew as the agreed recovery wage.', owner:'You deliver the sealed ledger and ask the clerk to make the workers’ copies; the miller pays three coins for recovery.', gear:'drainageHook', gearSource:'A duplicate from the mill’s own river crew, transferred by the miller as the agreed wage; the sealed ledger remains private property.', coins:3, knowledge:'Recovering a sealed record and resolving who may read it are separate tasks; preserve the seal and direct access through the proper parties.' },
  { id:'the-iron-at-milepost-nine', title:'Iron at Milepost Nine', subtitle:'A road crew disputes whether a buried tool was lost or deliberately left.', place:'roadside', risk:'LOW', opening:'A ditch crew uncovers a steel wedge and a compact pry tool beneath a milepost. The current foreman says neither belongs to his crew; an older worker recognizes the pry tool as county property from a job twenty years ago.', firstChoices:['Compare the county stamp with the crew’s current inventory','Ask the older worker where the old job records were stored','Lift the milepost base carefully to check for a second mark'], complication:'The stamped pry tool matches a retired county inventory. The wedge has no mark, but a nearby farmhand says the previous road crew left it after repairing a gate. The county confirms the pry tool should be returned.', consequence:['The stamp identifies the pry tool, while the wedge remains unclaimed but not yet clearly abandoned.','The old record shows the pry tool was written off; the county authorizes its transfer after inspection.','A second mark under the post records its setting date, but does not settle who owned the loose wedge.'], property:'The county takes back its stamped pry tool and authorizes the clean, unmarked Steel Wedge as yours because the former crew abandoned it in a public ditch under the signed clearance.', owner:'You return both items for a county review and accept the road crew’s two-coin inspection fee.', gear:'steelWedge', gearSource:'Formally released by the county after its stamped tool was returned and the unmarked wedge was confirmed abandoned in a public ditch.', coins:2, knowledge:'A property stamp can establish a public owner even when a tool has been written off; write-off and release are separate acts.' },
  { id:'the-bell-creek-drift', title:'The Bell Creek Drift', subtitle:'A flood has carried a freight strap into the branches, where two teams claim it.', place:'flooded field', risk:'MODERATE', opening:'A broad leather strap hangs from a willow after Bell Creek flooded. Two wagon teams lost freight nearby, and both show matching buckle stitching. The strap is wet and frayed near one loop.', firstChoices:['Use Heavy Leather Gloves to inspect the frayed loop','Ask each driver for the strap’s repair mark rather than its color','Reach from the bank with the Gate Hook instead of entering the water'], complication:'One driver produces a receipt for a matching Freightman’s Strap; the other recognizes a maker’s stamp but has no receipt. The strap can be dried and repaired, but its current owner must be established first.', consequence:['The gloves keep the rough wet leather from cutting your palm; the loop is damaged but repairable.','A tiny double stitch points to the first driver’s harness maker and supports the receipt.','The hook brings the strap to shore without exposing either claimant to the current.'], property:'The first driver takes the recovered strap after you arrange a repair. As thanks, the second driver transfers his own sound spare Freightman’s Strap, which has a distinct serial mark.', owner:'You return the identified strap to its owner and take two coins for the recovery and careful inspection.', gear:'freightmansStrap', gearSource:'A separate spare with its own mark, explicitly gifted by the second driver after his strap was confirmed safe; the flood-recovered strap goes to its documented owner.', coins:2, combat:{enemy:'aggressive wagon claimant',warning:'One claimant lunges for the strap after the mark is identified; the other driver is close enough to help, and the bank path remains open.',winChance:0.60}, repair:true, repairItem:'freightmansStrap', knowledge:'Matching color is weak evidence; stitch patterns, maker marks, and dated repair records distinguish similar work gear.' },
  { id:'the-snowbound-cache', title:'The Cache Beneath the Snow Fence', subtitle:'A winter cache is marked by a system no one present can fully read.', place:'mountain pass', risk:'HIGH', opening:'A snow slide has exposed a weatherproof bundle beneath a trail fence. A guide recognizes a three-notch expedition mark but says the party may still be on the mountain. The bundle includes a folded route note and the end of a rope.', firstChoices:['Use the Trail Compass to mark the safe return bearing','Probe snow from firm ground with the Sounding Rod','Call from the trail and wait for a response before untying the bundle'], complication:'The route note carries a name from a survey party that turned back last week. Its leader is found at a lower shelter, alive and searching for a missing assistant. The bundle is their shared reserve, not abandoned property.', consequence:['The compass marks the only visible return line before blowing snow erases it.','The rod finds a hollow pocket beside the fence, showing the bundle is not supporting the slope.','A reply comes from the lower shelter; the party is separated, not gone.'], property:'The survey leader recovers the shared reserve and gives you a duplicate Folding Trail Marker after the assistant is reunited and the cache inventory is checked.', owner:'You leave the reserve sealed for the party and receive a two-coin guide fee for locating them.', gear:'foldingTrailMarker', gearSource:'A duplicate marker transferred by the survey leader after the shared cache was returned and the separated assistant found.', coins:2, knowledge:'A marked cache may be temporarily unattended; identify the party’s status before treating stored equipment as abandoned.', lore:'The three-notch sign belonged to an old survey expedition that used fence posts as winter waypoints.' },
  { id:'the-pressroom-plates', title:'The Plates in the Pressroom', subtitle:'A closed newspaper office leaves printing plates claimed by two former partners.', place:'town warehouse', risk:'LOW', opening:'A newspaper office has closed. Its owner hired you to inventory the pressroom before the building is leased. A former printer arrives claiming the brass type and a Pocket Toolkit as unpaid wages; the owner says only the broken press is being cleared.', firstChoices:['Match the type cases against the office inventory','Ask both claimants to identify a repair mark on the toolkit','Separate personal hand tools from press fixtures before moving anything'], complication:'The toolkit has a private maker’s scratch and the printer names it correctly. The type cases belong to the paper, but one unopened case may hold a proof bearing a libel complaint.', consequence:['The inventory confirms the type is company property, not the printer’s personal kit.','The repair mark supports the printer’s claim, but the owner finds a dated receipt showing it was reimbursed.','The unopened case is kept sealed while the former partners discuss the complaint.'], property:'The owner settles the printer’s claim with the receipt and gives you the shop’s duplicate Pocket Toolkit, explicitly released as inventory compensation.', owner:'You leave the toolkit and type with their resolved owners and take three coins for the inventory work.', gear:'pocketToolkit', gearSource:'An inventoried duplicate explicitly released by the paper’s owner after the printer’s personal-property claim was resolved.', coins:3, knowledge:'A recognizable repair mark helps identify a tool, but a dated reimbursement record can establish who owns it now.' },
  { id:'the-boat-on-the-gravel', title:'The Boat on the Gravel Bar', subtitle:'A stranded skiff has a family’s property aboard and a ferryman’s gear lashed to it.', place:'river landing', risk:'MODERATE', opening:'A shallow river has left a skiff high on a gravel bar. Its owner is on the near bank, but the current makes the direct crossing unsafe. A coil of line and a Collapsible Water Pail are still aboard.', firstChoices:['Wait for the water to fall before approaching the skiff','Use the Sounding Rod to map the shallow channel from shore','Secure a line to the ferry post and ask the owner to guide a pull'], complication:'The pail belongs to the skiff owner; the line belongs to the ferry. A water-stained Weatherproof Blanket was left aboard by a prior passenger whose name is sewn into the hem.', consequence:['The falling water exposes the boat’s keel but leaves the passenger blanket and ferry line tangled.','The rod maps a shallow approach but finds a sudden drop at the far side.','The ferry line holds the skiff steady, but should be returned once the owner’s property is safe.'], property:'The prior passenger is reached by the ferryman and explicitly abandons the damaged blanket; the skiff owner gives you a duplicate Collapsible Water Pail for helping recover the boat.', owner:'You return the ferry line, pail, and named blanket to their owners and receive a two-coin recovery fee.', gear:'collapsibleWaterPail', gearSource:'A duplicate pail gifted by the skiff owner; the recovered pail and ferry line are returned to their owners, and the named blanket is released separately.', coins:2, knowledge:'A sounding rod can locate a safe shelf but not prove the whole crossing shallow; check the far edge before moving a boat.' },
  { id:'the-station-yard-heap', title:'The Heap Behind the Station', subtitle:'A pile of scrap includes a tool that the railway never meant to discard.', place:'railroad station', risk:'LOW', opening:'Behind a station, scrap iron is sorted for sale. A compact wrench sits among broken fittings, but its railway mark is still visible. The yard clerk says the pile was assembled by two shifts and cannot authorize every item himself.', firstChoices:['Separate marked railway equipment from private scrap','Ask the clerk to check the outgoing scrap ledger','Inspect the wrench for a repairer’s initials before lifting it'], complication:'The ledger lists the wrench as missing, not scrapped. A retired track worker recognizes the initials and says he lent it to a crew that later left the district. The company authorizes a search before any sale.', consequence:['The marked wrench is held aside; other scrap remains available to the buyer.','The missing entry prevents the tool from being treated as abandoned stock.','The initials identify a former borrower, but not whether the company later released it.'], property:'The railway confirms the wrench was formally written off and authorizes its transfer after you return the borrowed track gauge found beneath it.', owner:'You leave the wrench with the railway clerk and take two coins for correctly sorting the heap.', gear:'compactWheelWrench', gearSource:'Formally released by the railway after its borrowed track gauge was returned and the missing-tool ledger reconciled.', coins:2, combat:{enemy:'scrap-yard thief',warning:'A man who watched from the alley steps toward the wrench and shoves the clerk aside. He has no claim or inventory mark; the street and office door remain open.',winChance:0.56}, knowledge:'Scrap heaps can contain property recorded as missing; a sale pile is not itself proof that every marked object was released.' },
  { id:'the-tunnel-mouth', title:'The Pack at the Tunnel Mouth', subtitle:'A rockfall traps a traveler’s field kit outside the dangerous rubble.', place:'mountain tunnel', risk:'HIGH', opening:'A shallow rockfall has blocked one end of an old work tunnel. A pack sits just outside the rubble, with Field Bandage Roll and a marked Survey Chain visible. The absent owner’s horse waits tied nearby, calm but unattended.', firstChoices:['Call into the tunnel before moving the pack','Check the horse’s tack for a name or work mark','Use the Steel Wedge to keep a loose outer stone from rolling'], complication:'No one answers from inside. The pack list names a surveyor who was seen at the inn that morning; a second mark says the bandage roll was loaned to the tunnel crew. The rubble is not safe to enter.', consequence:['The tunnel remains silent; there is no evidence someone is trapped, but the inn is close enough to check.','The horse’s tag identifies the surveyor and his stable, making the pack’s owner verifiable.','The wedge keeps the outer stone from shifting while you retrieve only the pack outside the fall line.'], property:'The surveyor returns, claims the chain, and explicitly gives you his spare Field Bandage Roll after the borrowed roll is returned to the crew.', owner:'You keep the pack outside the tunnel and take it to the inn for its owner; the crew pays two coins for the safe recovery.', gear:'fieldBandageRoll', gearSource:'A spare roll transferred by the named surveyor after his property was returned and the crew’s loaned roll accounted for.', coins:2, knowledge:'A stable object outside a collapse can be recovered without entering the fall zone; silence does not prove the tunnel is empty.' },
  { id:'the-fence-line-find', title:'The Find Along the Fence Line', subtitle:'A storm uncovers a leather tool roll on disputed ground.', place:'farm', risk:'LOW', opening:'A storm has pulled fence posts from a boundary strip. Beneath one lies a Leather Repair Roll with a saddler’s mark. The two landholders disagree about who owns the strip, but neither claims the tool.', firstChoices:['Ask each landholder to describe the old fence repairs','Check the saddler’s stamp and nearby work order','Mark the exposed place and avoid crossing the disputed line'], complication:'The work order shows the roll was left by a traveling harness crew that finished the job and moved on. A local saddler recognizes the stamp and says the crew left its spare with him for safekeeping.', consequence:['The repair history predates the current boundary dispute and does not favor either landholder.','The stamp identifies the tool’s maker, while the work order names its custodian.','The exposed tool is left undisturbed until the saddler arrives with his record.'], property:'The saddler confirms the crew abandoned the spare to him; he sells it to you for one coin after the landholders jointly permit retrieval.', owner:'You leave the roll with its custodian and receive two coins for locating the missing work gear.', gear:'leatherRepairRoll', gearCost:1, gearSource:'Purchased for one coin from the saddler who held the former crew’s explicitly abandoned spare; both landholders consent to access.', coins:2, knowledge:'When a tool is found on disputed land, its work history and custodian can matter more than the fence line.' },
  { id:'the-glasshouse-gutter', title:'Glass from the Gutter', subtitle:'A broken greenhouse leaves sharp panes and a useful rain sheet.', place:'farm', risk:'MODERATE', opening:'A hailstorm broke the greenhouse roof. The gardener needs intact panes recovered from the gutter before rain ruins the seed beds. A Waxed Canvas Sheet lies nearby, but the gardener says it belongs to the estate.', firstChoices:['Put on Heavy Leather Gloves before clearing the pane fragments','Spread the estate’s sheet over the seed trays first','Use the Drainage Hook to pull loose glass toward a wooden box'], complication:'The seed trays are covered, but a cracked roof frame is still carrying glass above the doorway. Beneath it sits a travel cloak that belongs to the gardener, not the estate.', consequence:['The gloves protect against sharp edges, though they cannot make the overhead frame safe.','The sheet diverts rain from the seedlings, leaving less cover for the remaining panes.','The hook moves loose fragments from a distance; the cloak remains outside the work area until the frame is secured.'], property:'The gardener returns the cloak to its owner and explicitly gives you an unused Weatherproof Cloak from the estate stores as thanks for preserving the seed trays.', owner:'You finish covering the seedlings and return all estate material; the gardener pays three coins for the careful work.', gear:'weatherproofCloak', gearSource:'Estate-owned spare transferred by the gardener after the seed beds were protected; the nearby cloak is returned to its personal owner.', coins:3, knowledge:'Protect the living crop before recovering replaceable glass; leather gloves help with fragments but not unstable overhead frames.' },
  { id:'the-mineshaft-lamp', title:'The Lamp in the Upper Cut', subtitle:'A mine crew wants a lamp recovered without reopening a dangerous shaft.', place:'mine', risk:'HIGH', opening:'A mine is closed after water entered its lower workings. A lamp hangs above the upper cut, and the foreman says it belongs to the crew. A second light flickers deeper down, but no one can confirm whether it is another lamp or a reflection.', firstChoices:['Use the Roadman’s Lantern from the marked safe line','Call to the lower cut and wait for the echo to settle','Use the Compact Block-and-Tackle at the upper beam only'], complication:'The hanging lamp is reachable from the safe ledge; the lower glimmer shifts with water movement and is not evidence of a person. The foreman’s inventory says the upper lamp is a loaned spare, while your recovery agreement allows one cleared duplicate.', consequence:['Your shielded light reveals the hanger is sound enough to lower the lamp without entering the shaft.','The echo returns empty; the foreman keeps the lower cut closed.','The block lowers the lamp slowly, but its crew number must be checked before transfer.'], property:'The foreman returns the numbered loan lamp to the crew and releases a personally owned Roadman’s Lantern as your compensation for the safe recovery.', owner:'You leave both lamps with the crew and accept the agreed three-coin hazard fee.', gear:'roadmansLantern', gearSource:'Foreman’s own lantern explicitly transferred after the crew’s numbered loan lamp was returned; recovered from the safe upper cut.', coins:3, knowledge:'A reflected light can shift with water; do not infer a trapped worker from an unstable glow without corroborating signs.' },
  { id:'the-old-bridge-chest', title:'The Chest in the Old Bridge', subtitle:'A repair crew finds a sealed case between the stones, with no safe way to open it here.', place:'bridge', risk:'MODERATE', opening:'During bridge repairs, a mason uncovers a narrow lockable case between old stones. The county wants it recovered intact; a nearby family says their grandfather hid tools in the bridge during a flood. No one has a key.', firstChoices:['Use the Pocket Toolkit only to loosen the surrounding stone, not the lock','Ask the family for a distinctive contents detail','Record the stone position before moving the case'], complication:'A dated note in the family papers describes the case’s brass corner and a carpenter’s square inside. The county’s records describe a different sealed survey tube. The case can be lifted without opening it.', consequence:['The case slides free intact; the lock remains closed for its owner.','The family’s description matches details not visible from outside, supporting their claim.','The recorded stone position lets the county distinguish this case from the survey tube in its files.'], property:'The family opens the case with its original key and confirms the Square belonged to their late carpenter; they return it to the county and give you a duplicate Carpenter’s Square with the estate’s permission.', owner:'You deliver the sealed case to the family and receive three coins from the county for preserving the structure.', gear:'carpenterSquare', gearSource:'Duplicate from the family workshop gifted after the bridge case was identified and the original heirloom returned to its rightful owner.', coins:3, knowledge:'An object hidden in public infrastructure may have a private history; preserve the location and resolve the claim before opening it.' },
  { id:'the-warehouse-after-rain', title:'The Warehouse After Rain', subtitle:'A roof leak ruins a shipment, but one tool roll was never part of the cargo.', place:'warehouse', risk:'LOW', opening:'Rain came through a warehouse roof and soaked a stack of returned goods. The factor asks you to separate damaged stock from the tenant’s personal property before the morning inventory. A compact pry tool and two sealed crates sit under the drip.', firstChoices:['Move the sealed crates onto dry boards before inspecting contents','Check the tenant’s signed return list against the tool roll','Lay the Waxed Canvas Sheet to divert water from the inventory desk'], complication:'The pry tool is stamped to a former repair contractor who ended his lease last week. One crate contains returned goods; the other is a private trunk left behind by the tenant, who has not answered a letter.', consequence:['The crates are lifted without breaking the seals; the private trunk remains unopened.','The list places the pry tool with the contractor, not with the warehouse stock.','The sheet keeps the papers dry long enough to identify the trunk owner.'], property:'The contractor confirms the pry tool was his and explicitly sells it to you for one coin before leaving town; the private trunk is held for its tenant.', owner:'You hold the trunk for its owner and take two coins for sorting the inventory without opening sealed property.', gear:'foldingPryTool', gearCost:1, gearSource:'Sold directly by its named former contractor-owner for one coin after his mark was verified; it was never part of the warehouse stock.', coins:2, knowledge:'A returned shipment and a tenant’s left property are different claims; keep seals intact until the owner or inventory resolves them.' },
];

function build(story: SalvageStory): Scenario {
  const gearName = story.gear ? ITEMS[story.gear]?.name ?? story.gear : undefined;
  const tags = largeTags({
    hook: `${story.title}: recovery reveals a question of ownership before useful property can change hands.`,
    activity: 'labor/repair', role: 'worker', tone: story.risk === 'LOW' ? 'adventurous' : 'tense/dangerous',
    risk: story.risk, setting: story.place, combat: story.combat ? 'POSSIBLE' : 'NONE', fantasy: 'NONE',
    structures: ['multi-stage recovery', 'ownership evidence', 'partial salvage choice'], entry: ['hired/posted work'],
    rewards: [story.gear ? 'Gear' : 'coins', 'coins', 'reusable Knowledge', ...(story.lore ? ['Lore'] : [])],
    outcomes: ['success/partial success', 'walk-away/refusal', 'negotiated compromise'],
  });
  const scenes: Record<string, Scene> = {
    arrival: largeScene('arrival', story.title, story.opening, [
      { id:'carefulAccess', label:story.firstChoices[0], next:'evidence', effects:{ setFlags:[`${story.id}_access_one`] } },
      { id:'verifyFirst', label:story.firstChoices[1], next:'evidence', effects:{ setFlags:[`${story.id}_access_two`] } },
      { id:'holdAndAsk', label:story.firstChoices[2], next:'evidence', effects:{ setFlags:[`${story.id}_access_three`] } },
    ], story.risk === 'HIGH' ? 'warning' : 'safe'),
    evidence: largeScene('evidence', 'What the Recovery Shows', `${story.complication}${story.combat ? ` ${story.combat.warning}` : ''}`, [
      { id:'traceOwnership', label:'Trace the marks, records, and witnesses before claiming anything', next:'decision', effects:{ setFlags:[`${story.id}_checked_owner`] } },
      { id:'secureRecovery', label:'Secure only the clearly authorized item and leave the rest in place', next:'decision', effects:{ setFlags:[`${story.id}_limited_recovery`] } },
      { id:'deferRecovery', label:'Stop and ask the responsible owner or crew to settle the claim', next:'deferred', effects:{knowledge:[story.knowledge]} },
      ...(story.combat ? [{ id:'standGround', label:`Stand your ground and fight off the ${story.combat.enemy}`, hint:'The aggressor has made a clear physical threat; you can still withdraw or defer the recovery.', effects:{ combat:{ enemy:story.combat.enemy, winChance:story.combat.winChance, damageOnWin:1, damageOnLoss:3, winNext:'fightWon', lossNext:'fightLost' } } }] : []),
    ], story.risk === 'HIGH' ? 'warning' : 'safe', [
      { requirements:{ flags:[`${story.id}_access_one`] }, text:story.consequence[0] },
      { requirements:{ flags:[`${story.id}_access_two`] }, text:story.consequence[1] },
      { requirements:{ flags:[`${story.id}_access_three`] }, text:story.consequence[2] },
    ]),
    decision: largeScene('decision', 'The Property Is Accounted For', `${story.property} The recovered goods are now separated by owner. The item described above is offered only if you accept it below; the recovery fee is an alternative, not an additional payment. You may also decline all material compensation.`, [
      ...(story.gear ? [{ id:'acceptReleasedGear', label:story.gearCost ? `Buy the released ${gearName} for ${story.gearCost} coin${story.gearCost === 1 ? '' : 's'}` : `Accept the released ${gearName}`, requirements:{ notOwnedItems:[story.gear], ...(story.gearCost ? { minMoney:story.gearCost } : {}) }, next:'gear', effects:{ gainItems:[story.gear], ...(story.gearCost ? { money:-story.gearCost } : {}), gainItemProvenance:{ [story.gear]:story.gearSource ?? `Recovered with clear ownership release in ${story.title}` }, ...(story.repair ? { gainItemConditions:{ [story.gear]:'DAMAGED' as const } } : {}), historyFlags:[`salvage_${story.id}_${story.gear}`] } }] : []),
      ...(story.repairItem ? [{ id:'repairOwnedGear', label:`Have the recovery crew repair your damaged ${ITEMS[story.repairItem]?.name ?? story.repairItem} instead`, requirements:{ items:[story.repairItem], itemConditions:{ [story.repairItem]:['DAMAGED','BROKEN'] as ('DAMAGED'|'BROKEN')[] } }, next:'repaired', effects:{ repairItems:[story.repairItem], repairItemProvenance:{ [story.repairItem]:`Repaired during ${story.title}` }, historyFlags:[`salvage_${story.id}_repair`] } }] : []),
      { id:'takeFee', label:`Take the ${story.coins}-coin recovery fee instead`, next:'paid', effects:{ money:story.coins, setFlags:[`${story.id}_took_fee`] } },
      { id:'keepLesson', label:'Decline all material compensation', next:'lesson', effects:{ setFlags:[`${story.id}_refused`] } },
    ].map((choice)=>({...choice,effects:{knowledge:[story.knowledge],...choice.effects}})), 'safe', [
      { requirements:{ flags:[`${story.id}_checked_owner`] }, text:'Your inspection is entered beside the ownership marks, so the transfer applies only to the item explicitly released above.' },
      { requirements:{ flags:[`${story.id}_limited_recovery`] }, text:'Only the authorized recovery was moved; the remaining property stays where its owner can inspect it.' },
    ]),
    deferred: largeEnd('deferred', 'A Claim Left Intact', `You stop before disputed property changes hands. ${story.knowledge} The owner or responsible crew will decide what can be recovered.`),
    ...(story.combat ? {
      fightWon:largeScene('fightWon', 'The Threat Breaks', `The ${story.combat.enemy} backs away after the struggle. You do not search them or claim their belongings; the recovery question still has to be settled with the rightful owner.`, [{ id:'resumeRecovery', label:'Return to the documented recovery decision', next:'decision' }], 'warning'),
      fightLost:largeEnd('fightLost', 'A Costly Withdrawal', `You take a hard blow and withdraw rather than risk the recovery site. The property remains where it was, and nothing is added to your kit.`, 'success'),
    } : {}),
    ...(story.gear ? { gear:largeEnd('gear', 'Released Into Your Keeping', `${story.gearSource} You accept ${gearName}; it is placed through the normal carried-item reward flow, or held for placement if your capacity is full.${story.repair ? ` It still needs repair; that condition is recorded with its provenance.` : ''}`) } : {}),
    ...(story.repairItem ? { repaired:largeEnd('repaired', 'A Tool Restored', `The recovery crew repairs your ${ITEMS[story.repairItem]?.name ?? story.repairItem}; its condition is restored and the work is recorded in its provenance. You take no fee or new salvage Gear.`) } : {}),
    paid:largeEnd('paid', 'The Recovery Is Paid', `You take ${story.coins} coins rather than ${gearName ?? 'an item'}. The offered property remains with its released owner; no second compensation is added. ${story.owner}`),
    lesson:largeEnd('lesson', 'What the Marks Could Prove', `You leave without material compensation. ${story.knowledge}${story.lore ? ` The older account is also recorded: ${story.lore}` : ''}`),
    unpaid:largeEnd('unpaid', 'Nothing Claimed', 'You refuse compensation and leave the recovered property with the people whose ownership was established.'),
  };
  return largeAdventure(story.id, story.title, story.subtitle, tags, 'arrival', scenes);
}

export const SALVAGE_RECOVERY_GENRE_BATCH: Scenario[] = stories.map(build);
export const SALVAGE_RECOVERY_GENRE_IDS = new Set(SALVAGE_RECOVERY_GENRE_BATCH.map(({ id }) => id));
